import {
  type Rule,
  type Rules,
  type getYamlRootRuleSignature,
  ruleForPath,
  ruleValues,
  type suggestionsForExpressionSignature,
} from './yaml-rule-util'
import {findNode, getCurrentNode, getSimplifiedText, keysForPath, parse} from './utils'

export interface Suggestion {
  displayText: string
  snippet: Snippet
  replace: string
  description?: string
}

export interface Snippet {
  // odd elements will generate placeholders that the user can navigate pressing tabulator
  // e.g ['format(', 'string', ', ', '...values', ')']
  // In this case both "string" and "...values" will be placeholders
  tokens: string[]
  // Help information to show in the UI about each placeholder
  help?: string[]
  keepCursorLocation?: boolean
}

export interface Context {
  type?: string
  keys?: {
    [key: string]: Context | string
  }
  map?: Context
  resolver?: (workflow: unknown, path: string[]) => Promise<string[]>
}

/*
 * Used to not suggest already used values
 */
function usedValues(result: unknown, path: string[]): string[] {
  const arr = findNode(result, path)
  return Array.isArray(arr) ? arr.map(String) : []
}

/*
 * Used when filtering values.
 * Prevents infinite loop with editor.showHint() auto-completing the same thing already wrote
 */
export function startsWithAndNotEquals(prefix: string, text: string) {
  return text.startsWith(prefix) && prefix !== text
}

interface Text {
  text: string
}

export function filterValues<T extends string | Text>(
  values: T[],
  lastValue: string,
  ignoredValues: string[] = [],
): T[] {
  const lowerCasedLastValue = lastValue.toLowerCase()
  const lowerCasedIgnoredValues = ignoredValues.map(s => s.toLowerCase())
  return values.filter(value => {
    const valueLower = String((typeof value == 'object' && 'text' in value ? value.text : null) || value).toLowerCase()
    return startsWithAndNotEquals(lowerCasedLastValue, valueLower) && !lowerCasedIgnoredValues.includes(valueLower)
  })
}

export type ContextSuggestion = Text & {
  terminal: boolean
}

function autoCompleteAfterKey(rule: Rule): string {
  if (rule.single || rule.values) return ' '
  if (rule.rules && !rule.items && !rule.map) return '\n\t'
  if (!rule.rules && rule.items && !rule.map) return '\n\t- '
  return ''
}

export async function suggestionsFromValuesWithoutExpression(
  yaml: unknown,
  path: string[],
  rule: Rule,
  lastValue: string,
  ignoreItems: string[],
  makeItAnArray: boolean,
) {
  let values
  if (rule.single && rule.single.length === 1 && rule.single[0] === 'boolean') {
    values = ['true', 'false']
  } else if (rule.values) {
    values = await ruleValues(rule, yaml, path)
  } else return null

  const filtered = filterValues(values, lastValue, ignoreItems)
  if (filtered.length === 0) return null
  return filtered.map(str => ({
    displayText: str,
    snippet: {tokens: [makeItAnArray ? `[${str}]` : str]},
    replace: lastValue,
  }))
}

export function suggestionsFromRules(rules: Rules, lastValue: string, ignoreKeys: string[]): Suggestion[] {
  return filterValues(Object.keys(rules), lastValue, ignoreKeys).map(key => {
    const rule = rules[key]!
    const after = autoCompleteAfterKey(rule)
    return {
      displayText: key,
      snippet: {tokens: [`${key}:${after}`]},
      replace: lastValue,
      description: rule.description,
    }
  })
}

export async function autocomplete(
  fullText: string,
  textBeforeCursor: string,
  getRootRule: getYamlRootRuleSignature,
  suggestionsForExpression: suggestionsForExpressionSignature,
): Promise<Suggestion[] | null> {
  try {
    const {simplifiedText, lastLine} = getSimplifiedText(textBeforeCursor)
    const {result, lastValue: lastParsedValue, consumeKey} = parse(simplifiedText, '')
    const {path, lastValue: lastDataValue} = getCurrentNode(result)
    const lastValue = lastParsedValue != null ? lastParsedValue : lastDataValue
    if (consumeKey) path.pop()
    const nested = lastLine.match(/^\s*(-\s*)?$/) !== null || lastLine.indexOf(':') === -1
    const {result: workflow} = parse(textBeforeCursor, fullText.substring(textBeforeCursor.length))
    const ignoreKeys = keysForPath(workflow, path)
    const ignoreValues = usedValues(workflow, path)
    return await getSuggestions(
      getRootRule,
      suggestionsForExpression,
      workflow,
      path,
      lastValue,
      [...ignoreKeys, ...ignoreValues],
      nested,
    )
  } catch {
    return null
  }
}

export async function getSuggestions(
  getRootRule: getYamlRootRuleSignature,
  suggestionsForExpression: suggestionsForExpressionSignature,
  workflow: unknown,
  path: string[],
  lastValue: string,
  ignoreItems: string[],
  nested: boolean,
): Promise<Suggestion[] | null> {
  const rootRule = getRootRule({})
  const rule = ruleForPath(path, rootRule)
  if (!rule) return null

  const currentValue = findNode(workflow, path)
  const isArray = Array.isArray(currentValue)
  if (isArray && rule.multipleValues !== true) return null
  if (!nested || isArray || !rule.rules) {
    const makeItAnArray = !isArray && rule.multipleValues === true
    return (
      (suggestionsForExpression ? await suggestionsForExpression(workflow, path, lastValue) : null) ||
      (await suggestionsFromValuesWithoutExpression(workflow, path, rule, lastValue, ignoreItems, makeItAnArray))
    )
  }
  return suggestionsFromRules(rule.rules, lastValue, ignoreItems)
}

export function unescapeContext(name: string): string {
  const match = name.match(/^\.(.+)?|\['(.+?)('\])?$/)
  return match ? match[1] || match[2] || '' : name
}
